{
  "name": "QX量子电路客户端",
  "name_en": "QX Quantum Circuit Client",
  "manufacturer": "",
  "description": "一个非物理的软件客户端组件，用于通过网络连接 QX 量子电路服务，创建量子比特寄存器与量子电路、发送门操作命令、运行理想或含噪电路，并读取量子比特测量结果。",
  "description_en": "A non-physical software client component for connecting to a QX quantum circuit service over the network, creating qubit registers and circuits, sending gate commands, running ideal or noisy circuits, and retrieving qubit measurement results.",
  "tag_hints": [
    "quantum circuit execution",
    "quantum simulator client",
    "remote command interface",
    "qubit register management",
    "measurement readout",
    "noisy circuit simulation"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 QX 服务主机与端口。",
      "description_en": "Connect to the QX service host and port."
    },
    {
      "action_name": "auto-create_circuit",
      "description": "创建指定名称的量子电路，并用给定门命令构建该电路。",
      "description_en": "Create a named quantum circuit and build it from the provided gate commands."
    },
    {
      "action_name": "auto-create_qubits",
      "description": "创建指定数量的量子比特寄存器；如有需要会重置现有量子比特与电路。",
      "description_en": "Create a qubit register with the requested number of qubits; existing qubits and circuits may be reset if needed."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与 QX 服务的连接。",
      "description_en": "Disconnect from the QX service."
    },
    {
      "action_name": "auto-list_circuits",
      "description": "列出当前已创建的量子电路。",
      "description_en": "List the currently created quantum circuits."
    },
    {
      "action_name": "auto-remove_qubits",
      "description": "移除所有量子比特和电路，并重置服务端状态。",
      "description_en": "Remove all qubits and circuits and reset the server-side state."
    },
    {
      "action_name": "auto-run_circuit",
      "description": "运行指定名称的量子电路。",
      "description_en": "Run the specified quantum circuit."
    },
    {
      "action_name": "auto-run_noisy_circuit",
      "description": "使用指定噪声模型、误差概率和迭代次数运行含噪量子电路。",
      "description_en": "Run a noisy quantum circuit using the specified noise model, error probability, and iteration count."
    },
    {
      "action_name": "auto-send_cmd",
      "description": "向 QX 服务发送原始命令或批量门命令，并接收确认。",
      "description_en": "Send a raw command or batched gate commands to the QX service and receive acknowledgement."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取量子比特的测量结果。",
      "description_en": "Get qubit measurement result."
    },
    {
      "action_name": "auto-get_measurement_average",
      "description": "获取量子比特的平均测量结果。",
      "description_en": "Get qubit average measurement result."
    },
    {
      "action_name": "auto-get_nr_qubits",
      "description": "获取量子比特数量。",
      "description_en": "Get number of qubits."
    }
  ]
}

